            float4 v0 = __ldcs(&x4[i]);
            float4 v1 = __ldcs(&x4[i + stride]);
            float4 v2 = __ldcs(&x4[i + 2LL * stride]);
            float4 v3 = __ldcs(&x4[i + 3LL * stride]);
            v0 = sigmoid4_f(v0);
            v1 = sigmoid4_f(v1);
            v2 = sigmoid4_f(v2);
            v3 = sigmoid4_f(v3);
            __stcs(&y4[i], v0);
            __stcs(&y4[i + stride], v1);
            __stcs(&y4[i + 2LL * stride], v2);
            __stcs(&y4[i + 3LL * stride], v3);
        }
        for (; i < n4; i += stride) {
            __stcs(&y4[i], sigmoid4_f(__ldcs(&x4[i])));
        }
    } else {
        for (long long i = tid; i < n; i += stride) {
            __stcs(&y[i], sigmoid_f(__ldcs(&x[i])));
        }
    }
